{
  "certificate": {
    "number": "R76/2006-A-CZ1-2023.01",
    "scheme": "A",
    "page_total": 4,
    "member_state": "Czech Republic",
    "date_issued": "2023-02-13"
  },
  "issuing_authority": {
    "name": "Czech Metrology Institute",
    "address_lines": ["Okružní 31", "638 00 Brno", "Czech Republic"],
    "person_responsible": "Jan Kalandra",
    "person_title": "Head of Certification Body (signatory: RNDr. Pavel Klenovský)"
  },
  "applicants": [
    {
      "name": "RADWAG Wagi Elektroniczne Witold Lewandowski",
      "address_lines": ["5 Toruńska Street", "26-600 Radom", "Poland"]
    }
  ],
  "manufacturers": [
    {
      "name": "RADWAG Wagi Elektroniczne Witold Lewandowski",
      "address_lines": ["5 Toruńska Street", "26-600 Radom", "Poland"]
    }
  ],
  "certified_type": {
    "category": "Non-automatic weighing instrument",
    "type_designations": ["xxx.yyy.n.HRP.zzz", "xxx.yyy.n.HRP.EX.zzz"],
    "module_designation": "Not applicable",
    "description": "Series xxx.yyy.n.HRP.zzz (xxx – terminal name: 5Y, HY10 or 7.1; yyy – maximum range; n – optional pan size; zzz – optional design) consists of HRP weighing module which can be connected to 5Y, PUE HY10 or PUE 7.1 indicator. EX version xxx.yyy.n.HRP.EX.zzz operates with PUE HX5.EX indicator through dedicated power supplies PM01.EX (for terminals) and PM02.EX (for platforms)."
  },
  "model_family": {
    "family_name": "xxx.yyy.n.HRP.zzz series",
    "models": [
      {
        "model_id": "5Y.HRP",
        "label": "HRP weighing module with PUE CY10 (5Y) terminal",
        "attributes": {
          "terminal": "PUE CY10 (5Y)",
          "type_pattern": "xxx.yyy.n.HRP.zzz"
        }
      },
      {
        "model_id": "HY10.HRP",
        "label": "HRP weighing module with PUE HY10 indicator",
        "attributes": {
          "terminal": "PUE HY10",
          "type_pattern": "xxx.yyy.n.HRP.zzz"
        }
      },
      {
        "model_id": "7.1.HRP",
        "label": "HRP weighing module with PUE 7.1 indicator",
        "attributes": {
          "terminal": "PUE 7.1",
          "type_pattern": "xxx.yyy.n.HRP.zzz"
        }
      },
      {
        "model_id": "HRP.EX",
        "label": "EX version with PUE HX5.EX indicator",
        "attributes": {
          "terminal": "PUE HX5.EX",
          "type_pattern": "xxx.yyy.n.HRP.EX.zzz"
        }
      }
    ]
  },
  "components": [
    {
      "role": "weighing module",
      "type_designations": ["HRP"],
      "alternatives": null,
      "characteristics": {
        "software_version": {"value": "3.18 or 3.18EX (for EX versions)"},
        "outputs_supply_voltage_dc": {"value": {"min": 12, "max": 24}, "unit_symbol": "V"},
        "max_output_current": {"value": 100, "unit_symbol": "mA"},
        "control_input_voltage_range_dc": {"value": {"min": 12, "max": 24}, "unit_symbol": "V"},
        "optional_power_supply_input": {"value": {"min": 100, "max": 240}, "unit_symbol": "V"},
        "optional_power_supply_output": {"value": {"min": 12, "max": 24}, "unit_symbol": "V"},
        "interfaces": {"value": "RS 232, Ethernet, RS 485, Profibus, ProfiNet, CAN; additional not protected interfaces: digital I/O 2 inputs / 2 outputs or 4 inputs / 4 outputs; connectors and/or glands may be used for connection"}
      }
    },
    {
      "role": "indicator",
      "type_designations": ["PUE 7.1"],
      "alternatives": "OR",
      "characteristics": {
        "interfaces": {"value": "RS232, USB, Ethernet, Wi-Fi, 4 inputs / 4 outputs"}
      }
    },
    {
      "role": "indicator",
      "type_designations": ["PUE HY10"],
      "alternatives": "OR",
      "characteristics": {
        "ingress_protection": {"value": "IP 66/67"},
        "interfaces": {"value": "RS232, USB, Ethernet, 4 inputs / 4 outputs; optional: 12 inputs / 12 outputs, analog output, Profibus, RS485, CAN, Profinet, WiFi"}
      }
    },
    {
      "role": "terminal",
      "type_designations": ["PUE CY10 (5Y)"],
      "alternatives": "OR",
      "characteristics": {
        "software_version": {"value": "LL2.0"},
        "ingress_protection": {"value": "IP 32"},
        "interfaces": {"value": "2 x USB A, 1 x USB type C, Ethernet, HDMI, WiFi, RFID"}
      }
    },
    {
      "role": "indicator (EX versions)",
      "type_designations": ["PUE HX5.EX"],
      "alternatives": "OR",
      "characteristics": {
        "interfaces": {"value": "2 x RS232, RS 485 and optionally 4 inputs / 4 outputs (digital lines)"}
      }
    },
    {
      "role": "dedicated power supply (EX versions)",
      "type_designations": ["PM01.EX", "PM02.EX"],
      "alternatives": "OR",
      "characteristics": {
        "application": {"value": "PM01.EX – for terminals; PM02.EX – for platforms"}
      }
    },
    {
      "role": "optional alibi memory module",
      "type_designations": [],
      "alternatives": null,
      "characteristics": {
        "description": {"value": "Indicators PUE 7.1, PUE CY10, PUE HY10 or PUE HX5.EX can be equipped with a Memory module (Alibi memory) used as a database system acting as long-term memory; saves weighing results using embedded micro SD card or memory chip; data protected against deletion for a configurable period; HRP module alibi memory is disabled in configurations described by this certificate"}
      }
    }
  ],
  "characteristics": {
    "type_level": {
      "maximum_capacity": {"value": {"min": null, "max": 2000}, "unit_symbol": "kg", "footnote_markers": []},
      "verification_scale_interval": {"value": {"min": 1, "max": null}, "unit_symbol": "g", "footnote_markers": []},
      "multiple_range_operation": {"value": true, "unit_symbol": null, "footnote_markers": []},
      "operating_temperature": {"value": {"min": 10, "max": 40}, "unit_symbol": "°C", "footnote_markers": []},
      "relative_humidity": {"value": {"min": 15, "max": 80}, "unit_symbol": "%", "footnote_markers": []},
      "accuracy_class": {"value": "II or III", "unit_symbol": null, "footnote_markers": []},
      "software_version": {"value": "3.18 or 3.18EX (for EX versions)", "unit_symbol": null, "footnote_markers": []},
      "interface_compliance": {"value": "Interfaces must comply with clause 5.3.6 of OIML R 76 (2006)", "unit_symbol": null, "footnote_markers": []}
    },
    "model_level": [
      {
        "attribute": "power_supply_voltage",
        "unit_symbol": "V",
        "values": [
          {"model": "5Y.HRP", "value": {"min": 12, "max": 24}, "footnote_markers": []},
          {"model": "HY10.HRP", "value": {"min": 100, "max": 240}, "footnote_markers": []},
          {"model": "7.1.HRP", "value": {"min": 12, "max": 24}, "footnote_markers": []},
          {"model": "HRP.EX", "value": {"min": 100, "max": 240}, "footnote_markers": []}
        ]
      },
      {
        "attribute": "power_supply_type",
        "unit_symbol": null,
        "values": [
          {"model": "5Y.HRP", "value": "DC", "footnote_markers": []},
          {"model": "HY10.HRP", "value": "AC", "footnote_markers": []},
          {"model": "7.1.HRP", "value": "DC", "footnote_markers": []},
          {"model": "HRP.EX", "value": "AC", "footnote_markers": []}
        ]
      },
      {
        "attribute": "power_supply_frequency",
        "unit_symbol": "Hz",
        "values": [
          {"model": "HY10.HRP", "value": {"min": 50, "max": 60}, "footnote_markers": []},
          {"model": "HRP.EX", "value": {"min": 50, "max": 60}, "footnote_markers": []}
        ]
      },
      {
        "attribute": "ingress_protection",
        "unit_symbol": null,
        "values": [
          {"model": "5Y.HRP", "value": "IP 32", "footnote_markers": []},
          {"model": "HY10.HRP", "value": "IP 66/67", "footnote_markers": []},
          {"model": "7.1.HRP", "value": "IP 32", "footnote_markers": []}
        ]
      }
    ],
    "config_level": [
      {
        "attribute": "maximum_number_of_verification_scale_intervals",
        "axis": "accuracy_class",
        "values": [
          {"condition": "II", "value": {"min": null, "max": 32000}, "unit_symbol": null},
          {"condition": "III", "value": {"min": null, "max": 10000}, "unit_symbol": null}
        ]
      },
      {
        "attribute": "actual_scale_interval",
        "axis": "accuracy_class",
        "values": [
          {"condition": "II", "value": "0.1e ≤ d ≤ 1e", "unit_symbol": null},
          {"condition": "III", "value": "d = e", "unit_symbol": null}
        ]
      },
      {
        "attribute": "pan_size",
        "axis": "platform_configuration",
        "values": [
          {"condition": "platform without leverage", "value": "360 x 280", "unit_symbol": "mm"},
          {"condition": "platform without leverage with support construction", "value": "400 x 500", "unit_symbol": "mm"},
          {"condition": "platform with leverage", "value": "800 x 1000", "unit_symbol": "mm"},
          {"condition": "platform with double leverage", "value": "1250 x 1000", "unit_symbol": "mm"}
        ]
      }
    ]
  },
  "recommendation": {
    "id": "R76",
    "edition": 2006,
    "amendment": null,
    "scheme": "A",
    "accuracy_classes": ["II", "III"]
  },
